  FT["SG-H3281"] = {"id":"SG-H3281","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/MACMA2000-S516-2005?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Mutual Assistance in Criminal Matters (Malaysia) Order 2005","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation MACMA2000-S516-2005","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3281-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Order may be cited as the Mutual Assistance in Criminal Matters (Malaysia) Order 2005 and shall be deemed to have come into operation on 1st June 2005."}},{"id":"SG-H3281-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Declaration of Malaysia as prescribed foreign country"},"text":{"en":"2. Malaysia is hereby declared as a prescribed foreign country for the purposes of Part III of the Act."}}],"pack":"sg-p41"};
  FT["SG-H3282"] = {"id":"SG-H3282","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/MACMA2000-OR2?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Mutual Assistance in Criminal Matters (Prescribed Foreign Countries) Order","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation MACMA2000-OR2","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3282-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Mutual Assistance in Criminal Matters (Prescribed Foreign Countries) Order."}},{"id":"SG-H3282-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Declaration of prescribed foreign countries in respect of terrorism financing offences"},"text":{"en":"2.—(1) Subject to sub-paragraph (2), the countries specified in the Schedule are hereby declared as prescribed foreign countries for the purposes of Part III of the Act.\n(2) Assistance under sections 22, 26, 29 and 33 of the Act may, subject to the provisions of the Act, only be provided to the countries specified in the Schedule in respect of any terrorism financing offence as defined in section 2(1) of the Terrorism (Suppression of Financing) Act (Cap. 325)."}},{"id":"SG-H3282-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nParagraph 2\nPrescribed Foreign Countries\n1. The United Kingdom of Great Britain and Northern Ireland\n2. The United States of America."}}],"pack":"sg-p41"};
